--
-- Table structure for table `requirement_submissions`
--

CREATE TABLE `requirement_submissions` (
  `submission_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `building_type_id` int(11) NOT NULL,
  `needs_architect` tinyint(1) NOT NULL,
  `has_existing_design` tinyint(1) NOT NULL,
  `submission_status` enum('Pending','Approved','Rejected','Needs Revision') NOT NULL DEFAULT 'Pending',
  `user_id` int(11) DEFAULT NULL,
